// Parse BlackDuck-style raw scan text into structured rows.
// Mirrors src/parser.js -> parseBlackDuckLine in the React app.
const input = $input.first().json;
const raw = input['Scan Output (paste raw text)'] || input.scan_output || '';
const maxRaw = input['Max components to enrich'];
const max = parseInt(maxRaw, 10);
const limit = Number.isFinite(max) && max > 0 ? max : 20;

const meta = {
  provider: input['Provider'],
  model: input['Model'],
  apiKey: input['API Key'],
  githubToken: input['GitHub Token (optional)'] || '',
  ecosystem: (input['Ecosystem'] || 'npm').toLowerCase(),
};

function parseLine(line) {
  line = (line || '').trim();
  if (!line) return null;
  const layerMatch = line.match(/Layer\s+(\d+)/i);
  const layer = layerMatch ? parseInt(layerMatch[1], 10) : 0;
  const pctMatch = line.match(/(\d+)%/);
  const matchPercent = pctMatch ? parseInt(pctMatch[1], 10) : 100;
  const riskMatch = line.match(/\b(Critical|High|Medium|Low)\b/i);
  const risk = riskMatch
    ? riskMatch[1][0].toUpperCase() + riskMatch[1].slice(1).toLowerCase()
    : (/Ignored/i.test(line) ? 'Ignored' : 'None');
  const linkMatch = line.match(/(Dynamically Linked|Statically Linked|Not Linked)/i);
  const linkType = linkMatch ? linkMatch[1] : 'Unknown';
  const detMatch = line.match(/\b(Binary|Source|Signature|Manual)\b/i);
  const detectionType = detMatch ? detMatch[1] : 'Binary';
  const depMatch = line.match(/(Direct Dependency|Transitive|Development)/i);
  const depType = depMatch ? depMatch[1] : 'Direct Dependency';
  const licMatch = line.match(/(MIT|ISC|Apache-[\d.]+(?:-or-later)?|GPL-[\d.]+(?:-or-later|-only)?|LGPL-[\d.]+(?:-or-later|-only)?|BSD-[\d]+-Clause|MPL-[\d.]+|CC0-[\d.]+|Unlicense|CDDL-[\d.]+|EPL-[\d.]+)/i);
  const license = licMatch ? licMatch[1] : 'Unknown';

  const beforeLayer = line.split(/Layer\s+\d+/i)[0].trim();
  const tokens = beforeLayer.split(/\s+/);
  let version = '?', nameParts = tokens;
  for (let i = tokens.length - 1; i >= 0; i--) {
    if (/^\d[\d.]+/.test(tokens[i])) { version = tokens[i]; nameParts = tokens.slice(0, i); break; }
  }
  const name = nameParts.join(' ').replace(/\s*\(.*?\)/, '').trim() || beforeLayer;
  return { name, version, layer, depType, detectionType, matchPercent, linkType, license, risk, raw: line };
}

const rows = raw.split(/\r?\n/).map(parseLine).filter(Boolean).slice(0, limit);
return rows.map(r => ({ json: { ...r, ...meta } }));

// Merge OSV + npm + pypi results back onto the row.
const row = $('Split Rows').item.json;
const osvResp = $('OSV Vulnerability Query').item.json || {};
const npmResp = $('npm License Lookup').item.json || {};
const pypiResp = $('PyPI License Lookup').item.json || {};

const osvVulns = Array.isArray(osvResp.vulns) ? osvResp.vulns.map(v => ({ id: v.id, summary: v.summary, severity: (v.database_specific && v.database_specific.severity) || (v.severity && v.severity[0] && v.severity[0].score) || 'Unknown' })) : [];

let detectedLicense = row.license;
if (!detectedLicense || detectedLicense === 'Unknown') {
  if (row.ecosystem === 'npm') {
    if (typeof npmResp.license === 'string') detectedLicense = npmResp.license;
    else if (npmResp.license && npmResp.license.type) detectedLicense = npmResp.license.type;
  } else if (row.ecosystem === 'pypi') {
    detectedLicense = (pypiResp.info && pypiResp.info.license) || detectedLicense;
  }
}

return [{ json: { ...row, license: detectedLicense || 'Unknown', vulnerabilities: osvVulns, vuln_count: osvVulns.length } }];

// Extract LLM JSON output (handles both Anthropic and OpenAI-shaped responses)
// and attach the use-case classification onto the row.
const row = $('Merge Enrichment').item.json;
const llm = $input.first().json || {};

let text = '';
if (llm.content && Array.isArray(llm.content)) {
  text = llm.content.map(b => b.text || '').join('');
} else if (llm.choices && llm.choices[0] && llm.choices[0].message) {
  text = llm.choices[0].message.content || '';
}

function extract(t) {
  if (!t) return null;
  t = t.replace(/```json/gi, '').replace(/```/g, '').trim();
  const s = t.indexOf('{');
  const e = t.lastIndexOf('}');
  if (s === -1 || e === -1 || e <= s) return null;
  try { return JSON.parse(t.slice(s, e + 1)); } catch (_) { return null; }
}

const parsed = extract(text) || {};
const { apiKey, ...safeRow } = row;
return [{ json: { ...safeRow, useCase: parsed.category || 'Unknown', useCaseSummary: parsed.summary || '', riskNote: parsed.risk_note || '' } }];

// Aggregate the loop output into one final report.
const items = $input.all().map(i => i.json);
const totals = items.reduce((a, r) => {
  a.total += 1;
  a.byRisk[r.risk] = (a.byRisk[r.risk] || 0) + 1;
  a.byLicense[r.license] = (a.byLicense[r.license] || 0) + 1;
  a.byUseCase[r.useCase] = (a.byUseCase[r.useCase] || 0) + 1;
  a.totalVulns += (r.vuln_count || 0);
  return a;
}, { total: 0, byRisk: {}, byLicense: {}, byUseCase: {}, totalVulns: 0 });
return [{ json: { generatedAt: new Date().toISOString(), summary: totals, components: items } }];
